                        else
                        {
                            job = jobs[segment % jobs.Count];
                            if (job.Segments is null)
                            {
                                job.Segments = PooledList<(Memory<C0>, Memory<C1>, Memory<C2>, Memory<C3>)>.Rent();
                                job.Segments.Add((job.Memory1, job.Memory2, job.Memory3, job.Memory4));
                            }
                            job.Segments.Add((s0.AsMemory(start, length), s1.AsMemory(start, length), s2.AsMemory(start, length), s3.AsMemory(start, length)));
                        }
                        segment++;
                    }
                } while (join.Iterate());
            }
            if (batchSegments) foreach (var job in jobs)
            {
                countdown.AddCount();
                ThreadPool.UnsafeQueueUserWorkItem(job, true);
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, jobs);
            foreach (var job in jobs)
            {
                job.Segments?.Dispose();
                job.Segments = null;
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Memory4 = default;
                job.Action = null!;
                job.CountDown = null!;
            }
            JobPool<Work<C0, C1, C2, C3>>.Return(jobs);
            Workloads.Rethrow(faults);
        }

        /// <inheritdoc cref="Stream{C0}.Job{U}"/>
        [UnsupportedOSPlatform("browser", "browser-wasm runtime is single-threaded")]
        public void Job<U>(U uniform, UniformComponentAction<U, C0, C1, C2, C3> action)
        {
            AssertNoWildcards(StreamTypes);
            using var worldLock = World.Lock();
            var chunkSize = Math.Max(1, Count / Concurrency);

            using var countdown = new CountdownEvent(initialCount: 1);
            using var jobs = PooledList<UniformWork<U, C0, C1, C2, C3>>.Rent();
            var segment = 0;
            var workerLimit = Concurrency + 1; // Allow the rounding remainder without batching the dense case.
            var expectedSegments = 0;
            foreach (var table in Archetypes)
            {
                expectedSegments += table.Count / chunkSize + Math.Sign(table.Count % chunkSize);
            }
            var batchSegments = expectedSegments > workerLimit;

            foreach (var table in Archetypes)
            {
                using var join = table.CrossJoin<C0, C1, C2, C3>(StreamTypes.AsSpan());
                if (join.Empty) continue;
                var count = table.Count;
                var partitions = count / chunkSize + Math.Sign(count % chunkSize);

                do
                {
                    for (var chunk = 0; chunk < partitions; chunk++)
                    {
                        var start = chunk * chunkSize;
                        var length = Math.Min(chunkSize, count - start);

                        var (s0, s1, s2, s3) = join.Select;
                        UniformWork<U, C0, C1, C2, C3> job;
                        if (!batchSegments || jobs.Count < workerLimit)
                        {
                            job = JobPool<UniformWork<U, C0, C1, C2, C3>>.Rent();
                            job.Memory1 = s0.AsMemory(start, length);
                            job.Memory2 = s1.AsMemory(start, length);
                            job.Memory3 = s2.AsMemory(start, length);
                            job.Memory4 = s3.AsMemory(start, length);
                            job.Action = action;
                            job.Uniform = uniform;
                            job.CountDown = countdown;
                            jobs.Add(job);
                            if (!batchSegments)
                            {
                                countdown.AddCount();
                                ThreadPool.UnsafeQueueUserWorkItem(job, true);
                            }
                        }
                        else
                        {
                            job = jobs[segment % jobs.Count];
                            if (job.Segments is null)
                            {
                                job.Segments = PooledList<(Memory<C0>, Memory<C1>, Memory<C2>, Memory<C3>)>.Rent();
                                job.Segments.Add((job.Memory1, job.Memory2, job.Memory3, job.Memory4));
                            }
                            job.Segments.Add((s0.AsMemory(start, length), s1.AsMemory(start, length), s2.AsMemory(start, length), s3.AsMemory(start, length)));
                        }
                        segment++;
                    }
                } while (join.Iterate());
            }
            if (batchSegments) foreach (var job in jobs)
            {
                countdown.AddCount();
                ThreadPool.UnsafeQueueUserWorkItem(job, true);
            }
            countdown.Signal();
            countdown.Wait();

            List<Exception>? faults = null;
            Workloads.CollectFaults(ref faults, jobs);
            foreach (var job in jobs)
            {
                job.Segments?.Dispose();
                job.Segments = null;
                job.Memory1 = default;
                job.Memory2 = default;
                job.Memory3 = default;
                job.Memory4 = default;
                job.Action = null!;
                job.Uniform = default!;
                job.CountDown = null!;
            }
            JobPool<UniformWork<U, C0, C1, C2, C3>>.Return(jobs);
            Workloads.Rethrow(faults);
        }
        #endregion

        #region Raw
        /// <inheritdoc cref="Stream{C0}.Raw"/>
        public void Raw(MemoryAction<C0, C1, C2, C3> action)
        {
            AssertNotFamily();
            using var worldLock = World.Lock();
            foreach (var table in Archetypes)
            {
                using var join = table.CrossJoin<C0, C1, C2, C3>(StreamTypes.AsSpan());
                if (join.Empty) continue;
                var count = table.Count;
                do
                {
                    var (s0, s1, s2, s3) = join.Select;
                    var mem0 = s0.AsMemory(0, count);
                    var mem1 = s1.AsMemory(0, count);
                    var mem2 = s2.AsMemory(0, count);
                    var mem3 = s3.AsMemory(0, count);
                    action(mem0, mem1, mem2, mem3);
                } while (join.Iterate());
            }
        }

        /// <inheritdoc cref="Stream{C0}.Raw{U}"/>
        public void Raw<U>(U uniform, MemoryUniformAction<U, C0, C1, C2, C3> action)
